def split_csv(line):
    """
    Parse one line of CSV and return its fields as a list of strings.
    Returns None if the line is malformed.
    """
    if line == "":
        return [""]

    fields = []
    i = 0

    while i < len(line):
        # Parse one field
        if line[i] == '"':
            # Quoted field
            field = ""
            i += 1
            while i < len(line):
                if line[i] == '"':
                    # Check for doubled quote or end of quoted field
                    if i + 1 < len(line) and line[i + 1] == '"':
                        # Doubled quote
                        field += '"'
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        break
                else:
                    field += line[i]
                    i += 1
            else:
                # Reached end of line without closing quote
                return None

            # After closing quote, we must have comma or end of line
            if i < len(line) and line[i] != ',':
                return None

            fields.append(field)

            # Skip the comma if present
            if i < len(line) and line[i] == ',':
                i += 1
        else:
            # Unquoted field
            field = ""
            while i < len(line) and line[i] != ',':
                if line[i] == '"':
                    # Unquoted field cannot contain quotes
                    return None
                field += line[i]
                i += 1

            fields.append(field)

            # Skip the comma if present
            if i < len(line) and line[i] == ',':
                i += 1

    return fields

